if (
  entity.legalEntity &&
  !entity.factStorage &&
  !entity.periodLock &&
  entityOwnedMutableColumnNames(target, entity).includes(
    column.physicalName,
  )
) {
  await client.query(
    `GRANT UPDATE (${quoted(column.physicalName)})
       ON north_star_module.${quoted(entity.physicalTableName)}
       TO north_star_module_runtime`,
  );
}

if (numbering.prefix === VERIFICATION_SENTINEL_PREFIX)
  fail(
    id,
    `the prefix ${VERIFICATION_SENTINEL_PREFIX} is reserved for release verification sentinels`,
  );

const maximumLength = column.fieldContract.bounds.maximumLength;
if (maximumLength !== null && number.length > maximumLength)
  throw failure(
    'MODULE_DOCUMENT_SEQUENCE_EXHAUSTED',
    'the next document number no longer fits its field',
    field.fieldId,
  );

if (
  field.fieldType.kind === 'textFieldType' &&
  field.fieldType.maximumLength < VERIFICATION_SENTINEL_MINIMUM_LENGTH
)
  fail(
    id,
    `a number field holds at least ${String(VERIFICATION_SENTINEL_MINIMUM_LENGTH)} characters, so release verification sentinels keep 64 bits`,
  );

if (unreadable.length > 0) {
  throw failure(
    'VERIFICATION_PROBE_RECORD_UNREADABLE',
    `verification could not read its probe records to archive them: ${unreadable.join('; ')}`,
  );
}
